            saturated_axes |= (1u << 1);
        } else {
            command->command.y = req;
        }
    }

    // Z Axis
    {
        double req = requested_dipole_a_m2->z;
        double lim = per_axis_limit_a_m2->z;
        if (fabs(req) > lim) {
            command->command.z = ADCS_CLAMP(req, -lim, lim);
            saturated_axes |= (1u << 2);
        } else {
            command->command.z = req;
        }
    }

    command->saturated_axes = saturated_axes;

    // 4. Calculate realized torque: tau = m_limited cross B
    *torque_nm = adcs_vec3_cross(&command->command, field_body_t);

    return ADCS_OK;
}
